class Employee {
    private String employeeId;

    Employee(String employeeId) {
        this.employeeId = employeeId;
    }

    public int reward(double... fixedDeposits) {
        double sum = 0;
        for (double deposit : fixedDeposits) {
            sum += deposit;
        }

        if (sum > 1000000) {
            return 20000;
        } else if (sum >= 500000) {
            return 10000;
        } else {
            return 0;
        }
    }

    public String getEmployeeId() {
        return employeeId;
    }
}

public class Execute {
    public static void main(String[] args) {
        Employee employee1 = new Employee("E1001");
        int reward1 = employee1.reward(100000, 200000, 300000)// sum = 600000 → 10000 pts

        Employee employee2 = new Employee("E1002");
        int reward2 = employee2.reward(500000, 600000);     // sum = 1100000 → 20000 pts

        System.out.println(employee1.getEmployeeId() +" has got a reward of "+ reward1);
        System.out.println(employee2.getEmployeeId() +" has got a reward of "+ reward2);
    }

